using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Collections;
using System.Collections.Generic;
using Touchline;
public static class InferenceBenchmark {
 class Scenario {public string Name,Phase,Snapshot,ClubId,FixtureId;}
 class Variant {public string Name;public bool Compact,Short,Cache,OmitCache,MatchOnly;}
 class Row {public string Backend,Variant,Phase,Club,Error="",Decision;public int Round,Calls,InputTokens,OutputTokens;public double Seconds;public bool Fallback,Applied;public List<object> Timings=new List<object>();}
 class Agent:LocalModelAgent {
  readonly string endpoint;readonly int seed,limit;readonly bool cache,omit;public int Calls,Input,Output;public List<object> Timings=new List<object>();
  public Agent(string url,int value,int tokens,bool reuse,bool omitField=false):base(new AgentConfig{Enabled=true,Model="speed-test",Endpoint=url,TimeoutSeconds=180}){endpoint=url;seed=value;limit=tokens;cache=reuse;omit=omitField;}
  protected override async Task<string> Request(List<object> messages,object schema,CancellationToken ct){Calls++;using(var h=new HttpClientHandler{UseProxy=false})using(var client=new HttpClient(h)){client.Timeout=TimeSpan.FromSeconds(180);var body=AgentRequest.D("model","speed-test","messages",messages,"temperature",.35,"seed",seed,"max_tokens",limit,"response_format",new{type="json_object",schema=schema});if(!omit)body["cache_prompt"]=cache;var reply=await client.PostAsync(endpoint,new StringContent(Storage.Encode(body),Encoding.UTF8,"application/json"),ct);string raw=await reply.Content.ReadAsStringAsync();if(!reply.IsSuccessStatusCode)throw new Exception("HTTP "+(int)reply.StatusCode+" "+raw.Substring(0,Math.Min(300,raw.Length)));var root=Storage.Decode<Dictionary<string,object>>(raw);var usage=(Dictionary<string,object>)root["usage"];Input+=Convert.ToInt32(usage["prompt_tokens"]);Output+=Convert.ToInt32(usage["completion_tokens"]);if(root.ContainsKey("timings"))Timings.Add(root["timings"]);var choice=(Dictionary<string,object>)((IEnumerable)root["choices"]).Cast<object>().First();return Convert.ToString(((Dictionary<string,object>)choice["message"])["content"]);}}
 }
 static string project,output,endpoint,backend;static Process server;
 static void Log(string text){File.AppendAllText(Path.Combine(output,"progress.log"),DateTime.Now.ToString("s")+" "+text+Environment.NewLine,Encoding.UTF8);}
 static Scenario[] Inputs(){var g=GameFactory.New(20261029,false,"球星迭起");g.Week=6;g.PlayerClubId=g.Clubs.Last().Id;var c=g.Clubs[1];c.Upgrade=6;var fixture=g.Fixtures.First(f=>f.Week==6&&(f.Home==c.Id||f.Away==c.Id));var cases=new List<Scenario>();
  cases.Add(new Scenario{Name="six-week",Phase="阶段规划",Snapshot=Storage.Encode(g),ClubId=c.Id});
  var renewal=Storage.Clone(g);renewal.Phase="续约";renewal.Club(c.Id).Funds=700;foreach(var p in renewal.Squad(c.Id).OrderBy(p=>p.Value).Take(4)){p.Age=35;p.Favor=2;}cases.Add(new Scenario{Name="renewal",Phase="续约",Snapshot=Storage.Encode(renewal),ClubId=c.Id});
  var market=Storage.Clone(g);market.Phase="需求转会";foreach(var club in market.Clubs)club.Funds=15000;foreach(var p in market.Players.Where(p=>p.ClubId!=c.Id).OrderByDescending(p=>p.Value).Take(8))p.Listed=true;
  foreach(var p in market.Squad(c.Id).OrderByDescending(p=>p.Value).Take(2)){var buyer=market.Clubs.Last();market.Offers.Add(new TransferOffer{Id="speed-quote-"+p.Id,PlayerId=p.Id,SellerId=c.Id,BuyerId=buyer.Id,Fee=Transfers.Fee(market,p,false),Season=1});}
  cases.Add(new Scenario{Name="transfer",Phase="需求转会",Snapshot=Storage.Encode(market),ClubId=c.Id});
  var match=Storage.Clone(g);match.PlayerClubId=fixture.Home==c.Id?fixture.Away:fixture.Home;cases.Add(new Scenario{Name="player-prematch",Phase="赛前",Snapshot=Storage.Encode(match),ClubId=c.Id,FixtureId=fixture.Id});Football.Begin(match,match.Fixtures.First(f=>f.Id==fixture.Id));match.Live.Round=22;match.Live.HomeGoals=1;match.Live.AwayGoals=0;cases.Add(new Scenario{Name="player-halftime",Phase="中场",Snapshot=Storage.Encode(match),ClubId=c.Id,FixtureId=fixture.Id});return cases.ToArray();
 }
 static async Task Start(CancellationToken ct){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;listener.Stop();endpoint="http://127.0.0.1:"+port+"/v1/chat/completions";
  string runtime=Path.Combine(project,"LocalAI",backend=="cpu"?"runtime":"runtime-cuda","llama-server.exe");if(!File.Exists(runtime))runtime=Directory.GetFiles(Path.GetDirectoryName(runtime),"llama-server.exe",SearchOption.AllDirectories).First();
  string args="-m \""+Path.Combine(project,"LocalAI","qwen2.5-1.5b-instruct-q4_k_m.gguf")+"\" --host 127.0.0.1 --port "+port+" -c 8192 -t 8 -tb 8 --parallel 1 --cache-ram 512 --alias speed-test -ngl "+(backend=="cpu"?"0":"99");
  var info=new ProcessStartInfo(runtime,args){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=Path.GetDirectoryName(runtime),RedirectStandardOutput=true,RedirectStandardError=true};var diagnostic=new BoundedDiagnosticLog(Path.Combine(output,backend+"-server.log"),1024*1024);var watch=Stopwatch.StartNew();server=Process.Start(info);server.OutputDataReceived+=(s,e)=>{if(e.Data!=null)diagnostic.Write("stdout",e.Data);};server.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)diagnostic.Write("stderr",e.Data);};server.BeginOutputReadLine();server.BeginErrorReadLine();
  using(var h=new HttpClientHandler{UseProxy=false})using(var client=new HttpClient(h)){client.Timeout=TimeSpan.FromSeconds(2);bool ready=false;for(int i=0;i<180;i++){ct.ThrowIfCancellationRequested();if(server.HasExited)throw new Exception("Server exited "+server.ExitCode);try{ready=(await client.GetAsync("http://127.0.0.1:"+port+"/health",ct)).IsSuccessStatusCode;}catch{}if(ready)break;await Task.Delay(500,ct);}if(!ready)throw new Exception("Server startup timeout");}watch.Stop();File.WriteAllText(Path.Combine(output,backend+"-startup.json"),Storage.Encode(new{Seconds=watch.Elapsed.TotalSeconds,Backend=backend,Arguments=args}));Log("READY "+backend+" "+watch.Elapsed.TotalSeconds.ToString("F2")+"s");
 }
 static async Task<Row> Run(Scenario scenario,Variant variant,int round,CancellationToken ct){InferenceTuning.GpuOnlyShort=false;InferenceTuning.CompactInput=variant.Compact;InferenceTuning.ShortOutput=variant.Short;InferenceTuning.MatchOnlyShort=variant.MatchOnly;var g=Storage.Decode<Game>(scenario.Snapshot);var c=g.Club(scenario.ClubId);var f=scenario.FixtureId==null?null:g.Fixtures.First(x=>x.Id==scenario.FixtureId);var spec=AgentRequest.Build(g,c,scenario.Phase,f);var agent=new Agent(endpoint,20261029+round,CoachingPolicy.PlayerMatch(g,f)?500:scenario.Phase=="赛前"?150:spec.ReplyTokens,variant.Cache,variant.OmitCache);var row=new Row{Backend=backend,Variant=variant.Name,Phase=scenario.Phase,Club=c.Name,Round=round};var watch=Stopwatch.StartNew();try{var d=await agent.Decide(g,c,scenario.Phase,f,ct);row.Fallback=d.reason.Contains("固定程序兜底");LocalModelAgent.ValidateDecision(g,c,d,scenario.Phase,f);watch.Stop();double funds=g.Clubs.Sum(x=>x.Funds);DecisionOutput.Apply(g,c,d,scenario.Phase,f,s=>{});if(Math.Abs(funds-g.Clubs.Sum(x=>x.Funds))>.001)throw new Exception("Funds not conserved");if(g.Fixtures.Any(x=>x.Played))throw new Exception("Unexpected fixture advanced");row.Applied=true;row.Decision=Storage.Encode(d);}catch(Exception ex){row.Error=ex.GetBaseException().Message;}finally{watch.Stop();row.Seconds=watch.Elapsed.TotalSeconds;row.Calls=agent.Calls;row.InputTokens=agent.Input;row.OutputTokens=agent.Output;row.Timings=agent.Timings;}Log("DONE "+backend+" "+variant.Name+" "+scenario.Name+" r="+round+" "+row.Seconds.ToString("F2")+"s calls="+row.Calls+" fallback="+row.Fallback+" error="+row.Error);return row;}
 static void Stop(){try{if(server!=null&&!server.HasExited){server.Kill();server.WaitForExit(3000);}}finally{if(server!=null)server.Dispose();}}
 static void Main(string[] args){try{project=Path.GetFullPath(args[0]);output=Path.GetFullPath(args[1]);backend=args[2];Directory.CreateDirectory(output);typeof(Storage).GetField("Root").SetValue(null,Path.Combine(output,"isolated-profile"));L10n.Initialize();L10n.English=false;var inputs=Inputs();File.WriteAllText(Path.Combine(output,backend+"-inputs.json"),Storage.Encode(inputs));var variants=backend=="cpu"?new[]{new Variant{Name="baseline"},new Variant{Name="compact",Compact=true},new Variant{Name="short",Short=true}}:new[]{new Variant{Name="baseline"},new Variant{Name="compact",Compact=true},new Variant{Name="short",Short=true},new Variant{Name="combined",Compact=true,Short=true},new Variant{Name="combined-cache",Compact=true,Short=true,Cache=true},new Variant{Name="combined-default-cache",Compact=true,Short=true,OmitCache=true},new Variant{Name="selective-cache",Compact=true,Short=true,MatchOnly=true,Cache=true}};var rows=new List<Row>();using(var ct=new CancellationTokenSource(TimeSpan.FromMinutes(35))){Start(ct.Token).GetAwaiter().GetResult();for(int round=0;round<2;round++)foreach(var scenario in inputs)foreach(var variant in (round==0?variants:variants.Reverse())){rows.Add(Run(scenario,variant,round,ct.Token).GetAwaiter().GetResult());File.WriteAllText(Path.Combine(output,backend+"-results.json"),Storage.Encode(rows));}}
  File.WriteAllText(Path.Combine(output,backend+"-complete.json"),Storage.Encode(new{Passed=rows.All(x=>x.Error==""&&!x.Fallback&&x.Applied),Decisions=rows.Count,Requests=rows.Sum(x=>x.Calls),Scope="Five phases, two rounds with reversed variant order, fixed seeds, same model. cache_prompt=false for independent controls, true only in explicit cache variant. No season, no user saves."}));
 }catch(Exception ex){if(output!=null)File.WriteAllText(Path.Combine(output,(backend??"test")+"-failure.txt"),ex.ToString());Environment.ExitCode=1;}finally{Stop();}}
}
